-- Thêm 10 chất cho kho thực phẩm để xem ở "Xem đủ chất" (King chốt 02/11/2026): lấy từ cùng nguồn Viện Dinh dưỡng (trường nutrition của API kho thực phẩm, chép ngày 02/11/2026), số trên 100 g phần ăn được; Viện chưa có số thì để trống
-- Các chất: nước (g), chất xơ (g), canxi (mg), kali (mg), magie (mg), sắt (mg), vitamin A, RAE (µg), vitamin C (mg), vitamin D, D2 + D3 (µg), vitamin E (mg); nguồn, liên kết, ngày hiệu lực giữ ở cột sẵn có của từng dòng
ALTER TABLE thuc_pham
  ADD COLUMN nuoc_100g NUMERIC(9, 2) CHECK (nuoc_100g >= 0),
  ADD COLUMN chat_xo_100g NUMERIC(9, 2) CHECK (chat_xo_100g >= 0),
  ADD COLUMN canxi_mg_100g NUMERIC(9, 2) CHECK (canxi_mg_100g >= 0),
  ADD COLUMN kali_mg_100g NUMERIC(9, 2) CHECK (kali_mg_100g >= 0),
  ADD COLUMN magie_mg_100g NUMERIC(9, 2) CHECK (magie_mg_100g >= 0),
  ADD COLUMN sat_mg_100g NUMERIC(9, 2) CHECK (sat_mg_100g >= 0),
  ADD COLUMN vitamin_a_mcg_100g NUMERIC(9, 2) CHECK (vitamin_a_mcg_100g >= 0),
  ADD COLUMN vitamin_c_mg_100g NUMERIC(9, 2) CHECK (vitamin_c_mg_100g >= 0),
  ADD COLUMN vitamin_d_mcg_100g NUMERIC(9, 2) CHECK (vitamin_d_mcg_100g >= 0),
  ADD COLUMN vitamin_e_mg_100g NUMERIC(9, 2) CHECK (vitamin_e_mg_100g >= 0);

